package main

const knowledgeHTML = `<details id="knowledge-panel" class="card workspace-panel" role="tabpanel" aria-labelledby="knowledge-panel-tab" data-workspace-panel="models" hidden><summary>研究知識與擷取規則</summary><div class="section-heading"><h2>研究知識與擷取規則</h2><p>檢視研究反思，管理可還原的知識與資料擷取版本。</p></div><p>每輪結果會保存成效與提案。來源取得率不等於資料可信度。</p><button id="knowledge-refresh" type="button" class="ghost">更新研究知識</button><div id="reflection-list" class="cards"></div><div id="knowledge-list" class="cards"></div><details><summary>新增知識版本</summary><form id="knowledge-form"><label>類型<select name="kind"><option>SOURCE_RELIABILITY</option><option>RESEARCH_STRATEGY</option><option>ENDPOINT_PATTERN</option><option>AUTH_PATTERN</option><option>DISCOVERY_PATH</option><option>MODEL_ALIAS_RULE</option><option>VERIFICATION_OUTCOME</option><option>PROVIDER_RECIPE</option></select></label><label>對象<input name="subject" maxlength="240" required></label><label>資料 JSON<textarea name="data" required></textarea></label><label>已保存證據 ID（逗號分隔）<input name="evidence_ids" required></label><label>判斷理由<textarea name="reason" maxlength="1000" required></textarea></label><button>保存知識提案</button></form></details><details><summary>宣告式資料擷取</summary><p>指定唯讀 GET 與 JSON 欄位對照。測試通過後可確認啟用。</p><div id="connector-list" class="cards"></div><form id="connector-form"><label>Provider<select name="provider_id" id="connector-provider" required></select></label><label>規則名稱<input name="name" maxlength="120" value="quota" required></label><label>資料種類<select name="kind"><option>QUOTA</option><option>PRICING</option><option>BALANCE</option><option>USAGE</option><option>PERFORMANCE</option><option>NOTICE</option><option>CATALOG</option></select></label><label>端點 Path<input name="path" placeholder="/v1/quota" required></label><label>憑證用途<select name="credential_role"><option>INFERENCE</option><option>ACCOUNT_PAT</option><option>NONE</option></select></label><label>PAT 參照 ID（僅帳戶資料需要）<input name="pat_credential_id"></label><label>資料範圍<select name="scope"><option>MODEL_KEY_GROUP</option><option>MODEL_PROVIDER</option><option>ACCOUNT</option><option>CATALOG</option></select></label><label>清單 JSON Pointer<input name="root_pointer" placeholder="/data"></label><label>欄位對照 JSON<textarea name="fields" required placeholder='{"model_id":"/model","group":"/group","rpd":"/limits/rpd","tpd":"/limits/tpd"}'></textarea></label><label>單位<select name="unit"><option>REQUESTS</option><option>TOKENS</option><option>USD/1M tokens</option><option>USD/1K tokens</option><option>USD/token</option><option>USD</option><option>CREDITS</option><option>MS</option><option>TPS</option><option>NONE</option></select></label><label class="check"><input name="fixed_charge_absent" type="checkbox">定價證據明確沒有固定請求費</label><label>判斷理由<textarea name="reason" maxlength="1000" required></textarea></label><button>保存擷取草稿</button></form></details></details>`

const jsKnowledge = `
let knowledgeVersions=[],connectorVersions=[],knowledgeLoadVersion=0;
async function loadKnowledge(){const ticket=++knowledgeLoadVersion,[reflections,knowledge,connectors]=await Promise.all([api("/research/reflections"),api("/research/knowledge"),api("/connectors")]);if(ticket!==knowledgeLoadVersion)return;knowledgeVersions=knowledge;connectorVersions=connectors;const reports=$("reflection-list"),rules=$("knowledge-list"),profiles=$("connector-list");reports.replaceChildren();rules.replaceChildren();profiles.replaceChildren();reflections.slice(0,15).forEach(r=>item(reports,"研究反思 · "+r.report.status,new Date(r.at).toLocaleString()+" · "+r.report.http_requests+" 次 HTTP",()=>{const box=modal("本輪研究成效");factsView(box,"來源、語言、查詢與驗證",r.report);box.append(el("p","反思參照："+r.id));}));knowledge.slice(0,100).forEach(v=>item(rules,v.kind+" · v"+v.version,(v.active?"已啟用":"待判讀")+" · "+v.subject,()=>knowledgeDetail(v)));connectors.forEach(v=>item(profiles,v.name+" · v"+v.version,(v.active?"已啟用 · ":"")+v.status+" · "+v.config.kind,()=>connectorDetail(v)));if(!reports.children.length)item(reports,"還沒有反思","完成一輪研究後會保存成效。");if(!rules.children.length)item(rules,"還沒有知識提案","可以由 Assistant 根據保存的證據提出。");const select=$("connector-provider"),old=select.value;select.replaceChildren();providers.forEach(p=>option(select,p.id,p.name));if([...select.options].some(n=>n.value===old))select.value=old;}
function knowledgeDetail(v){const box=modal(v.kind+" · v"+v.version);box.append(el("p",v.reason),el("p",v.active?"此版本目前已啟用":"此版本尚未啟用"));factsView(box,"知識與依據",v);const form=el("form"),input=field(form,"修訂資料 JSON","textarea",JSON.stringify(v.data,null,2)),reason=field(form,"修訂理由","textarea");reason.required=true;form.append(el("button","保存新版本"));box.append(form);form.addEventListener("submit",async e=>{e.preventDefault();try{notice("正在保存知識…");await submit("/research/knowledge",{kind:v.kind,subject:v.subject,data:JSON.parse(input.value),reason:reason.value,evidence_ids:v.evidence_ids});$("detail").close();await loadKnowledge();notice("知識新版本已保存");}catch(e){notice(e.message,true);}});if(!v.active)action(box,"確認啟用此知識版本",async()=>{notice("正在啟用知識…");const result=await submit("/research/knowledge/activate",{id:v.id,expected_active_id:v.active_id||"",confirm:true});$("detail").close();await loadKnowledge();notice("知識版本已啟用");const undo=el("div",undefined,"actions");$("knowledge-list").prepend(undo);action(undo,"Undo 知識啟用",async()=>{notice("正在還原知識…");await submit("/versions/undo",{id:result.action_id,confirm:true});await loadKnowledge();notice("知識啟用已還原");});},false);}
function connectorDetail(v){const box=modal(v.name+" · v"+v.version);box.append(el("p",v.status+(v.active?" · 已啟用":" · 尚未啟用")),el("p",v.reason));factsView(box,"擷取規則與測試結果",v);const form=el("form"),label=el("label","測試使用的模型"),target=el("select");target.required=true;target.setAttribute("aria-label","測試使用的模型");myModels.filter(m=>m.state==="ACTIVE"&&m.enabled&&m.provider_id===v.provider_id).forEach(m=>option(target,key(m),m.model_id+" · "+connectionLabel(m)));label.append(target);form.append(label,el("button","測試資料擷取"));box.append(form);form.addEventListener("submit",async e=>{e.preventDefault();const button=form.querySelector("button");button.disabled=true;try{notice("正在測試擷取…");const result=await submit("/connectors/test",{id:v.id,selection:JSON.parse(target.value)});await loadKnowledge();const latest=connectorVersions.find(x=>x.id===v.id);if(latest)connectorDetail(latest);notice(result.status==="VALIDATED"?"擷取測試通過":"擷取尚未通過，已保存原因",result.status!=="VALIDATED");}catch(e){notice(e.message,true);}finally{button.disabled=false;}});if(v.status==="VALIDATED"&&!v.active)action(box,"確認啟用擷取規則",async()=>{notice("正在啟用規則…");const result=await submit("/connectors/activate",{id:v.id,expected_active_id:v.active_id||"",confirm:true});$("detail").close();await loadKnowledge();notice("擷取規則已啟用");const undo=el("div",undefined,"actions");$("connector-list").prepend(undo);action(undo,"Undo 擷取規則啟用",async()=>{notice("正在還原規則…");await submit("/versions/undo",{id:result.action_id,confirm:true});await loadKnowledge();notice("擷取規則已還原");});},false);const revise=el("form"),config=field(revise,"修訂規則 JSON","textarea",JSON.stringify(v.config,null,2)),reason=field(revise,"修訂理由","textarea");reason.required=true;revise.append(el("button","保存規則新版本"));box.append(revise);revise.addEventListener("submit",async e=>{e.preventDefault();try{await submit("/connectors",{provider_id:v.provider_id,name:v.name,config:JSON.parse(config.value),evidence_ids:v.evidence_ids,reason:reason.value});$("detail").close();await loadKnowledge();notice("新規則仍需測試及確認");}catch(e){notice(e.message,true);}});}
function bindKnowledge(){$("knowledge-panel").addEventListener("toggle",()=>{if($("knowledge-panel").open)loadKnowledge().catch(e=>notice(e.message,true));});$("knowledge-refresh").addEventListener("click",()=>loadKnowledge().catch(e=>notice(e.message,true)));$("knowledge-form").addEventListener("submit",async e=>{e.preventDefault();const v=data(e.target);try{await submit("/research/knowledge",{kind:v.kind,subject:v.subject,data:JSON.parse(v.data),evidence_ids:v.evidence_ids.split(",").map(s=>s.trim()).filter(Boolean),reason:v.reason});await loadKnowledge();notice("知識提案已保存");}catch(e){notice(e.message,true);}});$("connector-form").addEventListener("submit",async e=>{e.preventDefault();const v=data(e.target);try{await submit("/connectors",{provider_id:v.provider_id,name:v.name,reason:v.reason,config:{kind:v.kind,path:v.path,credential_role:v.credential_role,pat_credential_id:v.pat_credential_id,scope:v.scope,root_pointer:v.root_pointer,fields:JSON.parse(v.fields),unit:v.unit,fixed_charge_absent:e.target.elements.fixed_charge_absent.checked}});await loadKnowledge();notice("擷取草稿已保存，請先測試");}catch(e){notice(e.message,true);}});}
`
